import { newQuickJSWASMModuleFromVariant, shouldInterruptAfterDeadline, type QuickJSWASMModule } from "quickjs-emscripten-core";
import releaseSync from "@jitl/quickjs-wasmfile-release-sync";
import { transform } from "sucrase";

/** The element tree a card returns: plain data, never code. Our renderer turns it into React elements. */
export type CardNode = string | { type: string; props: Record<string, unknown>; children: CardNode[] };

// The card's code never sees the host: no imports, network, timers or storage. Elements are plain objects;
// Kit.X is just the name "kit:X", which our renderer maps to our own components.
const PRELUDE = `
const Fragment = "#fragment";
function flat(list, out) {
  for (const child of list) {
    if (Array.isArray(child)) flat(child, out);
    else if (child === null || child === undefined || child === false || child === true) continue;
    else if (typeof child === "object") out.push(child);
    else out.push(String(child));
  }
  return out;
}
function h(type, props, ...children) {
  const kids = flat(children, []);
  if (typeof type === "function") return type(Object.assign({}, props, { children: kids }));
  return { type: String(type), props: props || {}, children: kids };
}
const Kit = new Proxy({}, { get: (_, name) => "kit:" + String(name) });
const exports = {}; const module = { exports };
function require(name) { throw new Error("Cards cannot import modules (" + name + "); use Kit components."); }
`;

/** Compiles card TSX (written by the designer model) to a plain script; throws with the syntax error. */
export function compileCard(source: string) {
  return transform(source, { transforms: ["typescript", "jsx", "imports"], jsxPragma: "h", jsxFragmentPragma: "Fragment", production: true }).code;
}

let quickjs: Promise<QuickJSWASMModule> | undefined;
const engine = () => quickjs ??= newQuickJSWASMModuleFromVariant(releaseSync);

// Not a design limit: they only stop a runaway loop or allocation from stalling Home.
const DEADLINE_MS = 1000;
const MEMORY_BYTES = 64 * 1024 * 1024;

/**
 * Runs a compiled card in a fresh QuickJS context and returns its element tree as JSON-safe data.
 * Every render gets its own runtime, so nothing leaks between cards or workspaces.
 */
export async function runCard(compiled: string, input: { data: unknown; params: Record<string, string>; size: string }): Promise<CardNode> {
  const runtime = (await engine()).newRuntime();
  runtime.setMemoryLimit(MEMORY_BYTES);
  runtime.setMaxStackSize(1024 * 1024);
  runtime.setInterruptHandler(shouldInterruptAfterDeadline(Date.now() + DEADLINE_MS));
  const vm = runtime.newContext();
  try {
    const script = `${PRELUDE}\n${compiled}\n;(function () {
      const Card = module.exports.default || exports.default;
      if (typeof Card !== "function") throw new Error("The card must export a default function");
      return JSON.stringify(h(Card, JSON.parse(${JSON.stringify(JSON.stringify(input))})));
    })()`;
    const result = vm.evalCode(script, "card.js");
    if (result.error) {
      const error = vm.dump(result.error);
      result.error.dispose();
      throw new Error(`Card failed: ${typeof error === "object" && error ? (error.message ?? JSON.stringify(error)) : String(error)}`);
    }
    const json = vm.getString(result.value);
    result.value.dispose();
    return JSON.parse(json) as CardNode;
  } finally {
    vm.dispose();
    runtime.dispose();
  }
}
import { createHash } from "node:crypto";
import type { SupabaseClient } from "@supabase/supabase-js";
import type { requireWorkspace } from "@/lib/auth";
import { calendarDate } from "@/lib/finance/calendar";
import { artifactQueriesSchema, checkQueries, runArtifactQueries, type ArtifactQuery, type QueryShared } from "@/lib/ai/artifact-data";
import { cardParamsSchema, resolveParams, type CardParam, type ParamState } from "./params";
import { compileCard, runCard, type CardNode } from "./sandbox";
import { CardTreeError, sanitizeTree } from "./tree";
import { CARD_SIZE_KEYS, type CardSize } from "./sizes";

type Context = Awaited<ReturnType<typeof requireWorkspace>>;
export type CardVersion = { id: string; card_id: string; version: number; title: string; kind: "preset" | "code"; preset: string | null; compiled: string; queries: unknown; params: unknown };
export type CardRow = { id: string; artifact_id: string; title: string; size: string; published_version: number | null };
export type RenderedCard = { tree: CardNode | null; error: string | null; params: ParamState[] };
export const CARD_VERSION_COLUMNS = "id, card_id, version, title, kind, preset, compiled, queries, params";

/** Each card's CSS and ids are namespaced by this, so two cards never clash. */
export const cardScope = (cardId: string) => `c${cardId.replace(/-/g, "").slice(0, 12)}`;

// Same card version, size, params and data give the same tree, so a repeat view skips the sandbox. The data is
// part of the key, so a cached tree is never older than the data it was made from; scopes are checked before.
const cache = new Map<string, CardNode>();
const CACHE_ENTRIES = 500;
const RENDERER_VERSION = 1;
function remember(key: string, tree: CardNode) {
  cache.delete(key);
  cache.set(key, tree);
  if (cache.size > CACHE_ENTRIES) cache.delete(cache.keys().next().value!);
}

function definition(version: Pick<CardVersion, "queries" | "params">) {
  return { queries: artifactQueriesSchema.parse(version.queries), params: cardParamsSchema.parse(version.params) };
}

/** Runs the card's queries for today, then its code in the sandbox, then checks the tree. Errors become a message, never a broken Home. */
export async function renderCard(version: CardVersion, context: Context, { size, requested = {}, shared }: { size: CardSize; requested?: Record<string, string | undefined>; shared?: QueryShared }): Promise<RenderedCard> {
  const today = calendarDate(new Date(), context.settings.timezone);
  let params: ParamState[] = [];
  try {
    const { queries, params: declared } = definition(version);
    const { resolved, state } = resolveParams(declared, requested, today, context.workspace.locale);
    params = state;
    const data = await runArtifactQueries(queries, context, today, { params: resolved, shared });
    const input = { data, params: resolved.values, size };
    const key = createHash("sha256").update(JSON.stringify([RENDERER_VERSION, context.workspace.id, version.id, input])).digest("base64url");
    const hit = cache.get(key);
    if (hit) return { tree: hit, error: null, params };
    const tree = sanitizeTree(await runCard(version.compiled, input), { scope: cardScope(version.card_id) });
    remember(key, tree);
    return { tree, error: null, params };
  } catch (cause) {
    return { tree: null, error: `This card could not be shown: ${cause instanceof Error ? cause.message : "unknown error"}`, params };
  }
}

/** The param names a checked tree has a Kit.Param control for, tab panels included. */
function controls(node: CardNode, found = new Set<string>()): Set<string> {
  if (typeof node === "string") return found;
  if (node.type === "kit:Param") found.add(String(node.props.name));
  if (node.type === "kit:Tabs") for (const tab of node.props.tabs as { content: CardNode }[]) controls(tab.content, found);
  for (const child of node.children) controls(child, found);
  return found;
}

/**
 * Checks a new card before it is saved: it compiles, its queries are valid, and it renders a clean tree at
 * every size with today's data. The errors go back to the designer to fix.
 */
export async function checkCard(source: string, queries: ArtifactQuery[], params: CardParam[], context: Context) {
  let compiled: string;
  try { compiled = compileCard(source); } catch (cause) { return { errors: [`Syntax: ${cause instanceof Error ? cause.message : String(cause)}`] }; }
  const today = calendarDate(new Date(), context.settings.timezone);
  const { resolved } = resolveParams(params, {}, today, context.workspace.locale);
  const queryErrors = checkQueries(queries, today, resolved);
  if (queryErrors.length) return { errors: queryErrors };
  const data = await runArtifactQueries(queries, context, today, { params: resolved });
  const errors: string[] = [];
  for (const size of CARD_SIZE_KEYS) {
    try {
      const tree = sanitizeTree(await runCard(compiled, { data, params: resolved.values, size }), { scope: "check" });
      // A control the card declares must be on it, at every size; otherwise the user asked for it and never sees it.
      const shown = controls(tree);
      const missing = params.filter(param => !shown.has(param.name)).map(param => param.name);
      if (missing.length) errors.push(`${size}: declared params without a <Kit.Param name="…" /> control: ${missing.join(", ")}`);
    }
    catch (cause) { errors.push(`${size}: ${cause instanceof CardTreeError ? "" : "runtime "}${cause instanceof Error ? cause.message : String(cause)}`); }
  }
  return errors.length ? { errors } : { compiled, errors, data };
}

/** The version a card shows: the one asked for (a draft preview), or the published one. */
export async function loadCardVersion(supabase: SupabaseClient, workspaceId: string, cardId: string, version?: number | null) {
  const query = supabase.from("artifact_card_versions").select(CARD_VERSION_COLUMNS).eq("workspace_id", workspaceId).eq("card_id", cardId);
  const { data, error } = await (version ? query.eq("version", version) : query.order("version", { ascending: false }).limit(1)).maybeSingle();
  if (error) throw error;
  return data as CardVersion | null;
}

import { z } from "zod";
import { resolveToken, type ResolvedParams } from "@/lib/ai/artifact-data";

const name = z.string().regex(/^[a-zA-Z_][a-zA-Z0-9_]{0,39}$/);
const PERIODS = { "7d": "7 days", "30d": "30 days", "90d": "90 days", "6m": "6 months", "12m": "12 months", mtd: "This month", ytd: "This year" } as const;
type Period = keyof typeof PERIODS;

/** Controls a card offers on Home. Values are only ever picked from these options, so a request can't widen what a card reads. */
export const cardParamSchema = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("month"), name, months: z.number().int().min(2).max(24).default(12), default: z.enum(["current", "previous"]).default("current") }).strict(),
  z.object({ kind: z.literal("period"), name, options: z.array(z.enum(Object.keys(PERIODS) as [Period, ...Period[]])).min(2).max(7), default: z.enum(Object.keys(PERIODS) as [Period, ...Period[]]) }).strict(),
  z.object({ kind: z.literal("choice"), name, options: z.array(z.object({ value: z.string().min(1).max(100), label: z.string().min(1).max(40) }).strict()).min(2).max(12), default: z.string().min(1).max(100) }).strict(),
]);
export const cardParamsSchema = z.array(cardParamSchema).max(4).refine(params => new Set(params.map(param => param.name)).size === params.length, "Param names must be unique")
  .refine(params => params.every(param => param.kind === "month" || (param.kind === "period" ? param.options.includes(param.default) : param.options.some(option => option.value === param.default))), "Each default must be one of its options");
export type CardParam = z.infer<typeof cardParamSchema>;
/** What the card (and its controls) are told: each param's value and the options to pick from. */
export type ParamState = { name: string; value: string; options: { value: string; label: string }[] };

function periodRange(period: Period, today: string) {
  const from = period === "mtd" ? resolveToken("@month_start", today)
    : period === "ytd" ? resolveToken("@year_start", today)
    : period.endsWith("m") ? resolveToken(`@month_start:${1 - Number(period.slice(0, -1))}`, today)
    : resolveToken(`@days_ago:${Number(period.slice(0, -1)) - 1}`, today);
  return { from, to: today };
}

/** Requested values checked against each param's options; anything else falls back to the default. */
export function resolveParams(declared: CardParam[], requested: Record<string, string | undefined>, today: string, locale = "en"): { resolved: ResolvedParams; state: ParamState[] } {
  const resolved: ResolvedParams = { values: {}, ranges: {} };
  const state = declared.map((param): ParamState => {
    const wanted = requested[param.name];
    if (param.kind === "month") {
      const options = Array.from({ length: param.months }, (_, index) => {
        const start = resolveToken(`@month_start:${-index}`, today);
        return { value: start.slice(0, 7), label: new Intl.DateTimeFormat(locale, { month: "short", year: index >= 12 || start.slice(0, 4) !== today.slice(0, 4) ? "2-digit" : undefined, timeZone: "UTC" }).format(new Date(`${start}T00:00:00Z`)) };
      }).reverse();
      const value = options.some(option => option.value === wanted) ? wanted! : resolveToken(param.default === "previous" ? "@month_start:-1" : "@month_start", today).slice(0, 7);
      const from = `${value}-01`;
      const offset = (Number(value.slice(0, 4)) - Number(today.slice(0, 4))) * 12 + Number(value.slice(5, 7)) - Number(today.slice(5, 7));
      resolved.ranges[param.name] = { from, to: offset === 0 ? today : resolveToken(`@month_end:${offset}`, today) };
      resolved.values[param.name] = value;
      return { name: param.name, value, options };
    }
    if (param.kind === "period") {
      const value = (param.options as string[]).includes(wanted ?? "") ? wanted as Period : param.default;
      resolved.ranges[param.name] = periodRange(value, today);
      resolved.values[param.name] = value;
      return { name: param.name, value, options: param.options.map(option => ({ value: option, label: PERIODS[option] })) };
    }
    const value = param.options.some(option => option.value === wanted) ? wanted! : param.default;
    resolved.values[param.name] = value;
    return { name: param.name, value, options: param.options };
  });
  return { resolved, state };
}

